GimCorpus.put(484,0,[[6,13,"שבין השמשות ספק הוא וספק העירוב כשר. (א\"ה עיין בדברי הרב המחבר פ\"ד מהלכות בכורות דין א'):",1,0],[6,22,"הרוצה לשלח עירובו ביד אחר וכו'. (א\"ה מבואר בפרק בכל מערבין דהיינו משום דחזקה שליח עושה שליחותו, ועיין בדברי הרב המחבר פרק ד' מהלכות בכורות שהאריך למעניתו בפרט זה. ושם יתבאר דהיכא דהשליח מעצמו אמר שרוצה לעשות פעולה אחת סמכינן אחזקה זו אפילו לקולא יע\"ש): סליקו להו הלכות עירובין",1,0]]);
